#include <stdio.h>
/* ex08：传输时延 vs 传播时延 —— 两个「时延」根本不是一回事
 * 传输时延（发送时延）= 数据长度 / 发送速率   （把比特推上线路的时间）
 * 传播时延           = 链路长度 / 信号传播速度（比特在介质里跑的时间）
 * 时延带宽积         = 传播时延 × 带宽        （"管道里能装多少比特"）
 * 这三个量是 408 计算题的基本盘，也是理解「为什么卫星链路 RTT 那么大」的关键。*/
int main(void) {
    double c_fiber = 2.0e8;            /* 光在光纤中约 2×10^8 m/s（真空 3×10^8） */
    struct { const char *name; double len_km; double Mbps; int pkt_bit; } links[] = {
        {"同机房（10m 光纤）",   0.01,   10000.0, 12000},
        {"同城（50km 光纤）",    50.0,    1000.0, 12000},
        {"跨省（2000km 光纤）", 2000.0,    100.0, 12000},
        {"卫星（36000km）",   36000.0,     50.0, 12000}
    };

    printf("一个 12000 bit（1500 字节）的包，在四种链路上的时延分解\n");
    printf("--------------------------------------------------------------------------\n");
    printf("%-22s %-12s %-12s %-12s %s\n", "链路", "传输时延", "传播时延", "时延带宽积", "谁占主导");
    for (int i = 0; i < 4; i++) {
        double len_m = links[i].len_km * 1000.0;
        double rate_bps = links[i].Mbps * 1e6;
        double t_trans = links[i].pkt_bit / rate_bps * 1000.0;      /* ms */
        double t_prop = len_m / c_fiber * 1000.0;                   /* ms */
        double bdp = t_prop / 1000.0 * rate_bps / 8.0;              /* 字节 */
        printf("%-22s %-12.3f %-12.3f %-12.0f %s\n",
               links[i].name, t_trans, t_prop, bdp,
               t_prop > t_trans * 10 ? "传播时延（距离）" : "传输时延（带宽）");
    }
    printf("--------------------------------------------------------------------------\n");
    printf("读法：\n");
    printf("  1) 同机房：带宽高，传输时延可忽略，瓶颈在「推上线路」；\n");
    printf("  2) 跨省/卫星：传播时延由光速和距离决定，加带宽完全没用；\n");
    printf("  3) 卫星 36000km 单程 180ms，一来一回 RTT ≥ 360ms ——\n");
    printf("     所以 TCP 在卫星链路上慢，不是因为带宽，而是因为 RTT。\n");
    return 0;
}
